/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: LookupPlanInput, PlannedLookupQuery, LookupPlan
 *   Functions: isCompanyLikeName, splitCreditedNames, cleanFolderName, planMetadataLookup
 * Internal
 *   Functions: term, tagTerm, buildable, canonical
 *   Constants: companySuffix, japaneseCompany, formatToken
 * @end-catalog */

import { METADATA_LOOKUP_LIMITS } from './lookupContract';
import { cleanLookupTerm, isPlaceholderCredit, lookupTermProblem, normalizeGtin, normalizeIsrc, normalizeMusicBrainzId } from './lookupIdentifiers';
import { musicBrainzLuceneQuery, type MusicBrainzRecordingQuery, type MusicBrainzReleaseQuery } from './musicBrainzClient';

/**
 * Pure planner from the import's evidence to at most six MusicBrainz queries: valid embedded
 * identifiers first, then album or song text, then a cleaned folder name. It accepts names, never
 * links or file names; an identifier that fails its format check is dropped and never sent. Submitted
 * text is only normalized (NFC, collapsed whitespace), so a link, an over-long name or a control or
 * format character rejects the plan; tag and folder text is cleaned instead.
 */
export type LookupPlanInput = {
    trigger: 'submitted' | 'tags' | 'folder';
    submitted?: { kind: 'album' | 'song'; text: string };
    tags?: { album: string | null; albumArtist: string | null; title: string | null; artist: string | null };
    folderName?: string | null;
    fileCount: number;
    /** Values shared by every selected file. */
    identifiers?: { releaseId?: string | null; barcode?: string | null; catalogNumber?: string | null; isrc?: string | null };
};
export type PlannedLookupQuery =
    | { kind: 'musicBrainzRelease'; releaseId: string; basis: 'releaseId' }
    | { kind: 'musicBrainzReleaseSearch'; query: MusicBrainzReleaseQuery; basis: 'barcode' | 'catalogNumber' | 'albumText' | 'folder' }
    | { kind: 'musicBrainzRecordingSearch'; query: MusicBrainzRecordingQuery; basis: 'songText' }
    | { kind: 'musicBrainzIsrc'; isrc: string; basis: 'isrc' };
export type LookupPlan = { queries: PlannedLookupQuery[]; rejected: null | 'url' | 'tooLong' | 'invalidText' | 'empty' };

const term = (value: unknown): string | null => {
    try { return cleanLookupTerm(value, METADATA_LOOKUP_LIMITS.termLength); } catch { return null; }
};
/** Cleaned tag or folder text: format characters (a pasted U+200B, a BOM) are removed and control characters become spaces. */
const tagTerm = (value: unknown): string | null => typeof value === 'string' && value.length <= 4 * METADATA_LOOKUP_LIMITS.termLength + 64
    ? term(value.replace(/\p{Cf}/gu, '').replace(/\p{Cc}/gu, ' ')) : null;

const companySuffix = /(?:^|[\s,(])(?:records|recordings|entertainment|games|studios?|inc\.?|incorporated|ltd\.?|limited|llc|llp|plc|gmbh|k\.k\.|corp\.?|corporation|co\.,?\s*ltd\.?|co\.)(?=$|[\s,.)])/i;
const japaneseCompany = /株式会社|有限会社|合同会社|\(株\)|（株）|レコード|レコーズ|エンタテインメント|エンターテインメント/;

/** Heuristic for a label credited beside artists, such as `Asylum Records` or `株式会社Yostar`. */
export const isCompanyLikeName = (name: string): boolean => companySuffix.test(name) || japaneseCompany.test(name);

/** Splits a credited-names tag on ` / ` only; company-like fragments become label terms and placeholders are dropped. */
export const splitCreditedNames = (text: string | null | undefined): { artists: string[]; labels: string[] } => {
    const artists: string[] = [], labels: string[] = [];
    for (const fragment of (text ?? '').split(' / ')) {
        const name = tagTerm(fragment);
        if (!name || isPlaceholderCredit(name)) continue;
        (isCompanyLikeName(name) ? labels : artists).push(name);
    }
    return { artists, labels };
};

const formatToken = /^(?:\d{4}|flac|mp3|320|320k|320kbps|web|cd|hi-res|hires|24bit|16bit|24-bit|16-bit|\d{2,3}(?:\.\d)?khz|24-\d{2,3}|16-\d{2,3})$/i;

/** Removes bracketed year and format groups such as `[FLAC 24bit/96kHz]` or `(2017)`, then cleans the name. */
export const cleanFolderName = (name: string | null | undefined): string | null => {
    if (typeof name !== 'string' || name.length > 1024) return null;
    const stripped = name.replace(/\[([^[\]()]*)\]|\(([^[\]()]*)\)/g, (group, square: string | undefined, round: string | undefined) => {
        const tokens = (square ?? round ?? '').split(/[\s,/+_]+/).filter(Boolean);
        return tokens.length && tokens.every(token => formatToken.test(token)) ? ' ' : group;
    });
    return tagTerm(stripped);
};

/** A combined query longer than the MusicBrainz query bound is dropped rather than sent truncated. */
const buildable = (query: PlannedLookupQuery) => {
    if (query.kind !== 'musicBrainzReleaseSearch' && query.kind !== 'musicBrainzRecordingSearch') return true;
    try { musicBrainzLuceneQuery(query.query); return true; } catch { return false; }
};

const canonical = (value: unknown): string => {
    if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
    if (value && typeof value === 'object') return `{${Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${canonical((value as Record<string, unknown>)[key])}`).join(',')}}`;
    return JSON.stringify(value);
};

export const planMetadataLookup = (input: LookupPlanInput): LookupPlan => {
    if (input.trigger === 'submitted' && input.submitted) {
        const problem = lookupTermProblem(input.submitted.text, METADATA_LOOKUP_LIMITS.termLength);
        if (problem === 'url' || problem === 'tooLong' || problem === 'invalidText') return { queries: [], rejected: problem };
    }
    const queries: PlannedLookupQuery[] = [];
    const tags = input.tags;
    const credited = splitCreditedNames(tags?.albumArtist ?? tags?.artist ?? null);
    const songArtist = splitCreditedNames(tags?.artist ?? tags?.albumArtist ?? null).artists[0];
    const albumQueries = (release: string, basis: 'albumText' | 'folder', artist = credited.artists[0], label = credited.labels[0]) => {
        queries.push({ kind: 'musicBrainzReleaseSearch', query: { release, ...(artist ? { artist } : {}), ...(label ? { label } : {}) }, basis });
        queries.push({ kind: 'musicBrainzReleaseSearch', query: { release }, basis });
    };
    const songQueries = (recording: string) => {
        if (songArtist) queries.push({ kind: 'musicBrainzRecordingSearch', query: { recording, artist: songArtist }, basis: 'songText' });
        queries.push({ kind: 'musicBrainzRecordingSearch', query: { recording }, basis: 'songText' });
    };
    const folderQueries = () => {
        const folder = cleanFolderName(input.folderName);
        if (!folder) return;
        const parts = folder.split(' - ');
        const artist = parts.length === 2 ? tagTerm(parts[0]) : null, release = parts.length === 2 ? tagTerm(parts[1]) : null;
        if (artist && release && !isPlaceholderCredit(artist)) queries.push({ kind: 'musicBrainzReleaseSearch', query: { artist, release }, basis: 'folder' });
        queries.push({ kind: 'musicBrainzReleaseSearch', query: { release: folder }, basis: 'folder' });
    };

    const identifiers = input.identifiers ?? {};
    const releaseId = normalizeMusicBrainzId(identifiers.releaseId);
    if (releaseId) queries.push({ kind: 'musicBrainzRelease', releaseId, basis: 'releaseId' });
    const barcode = normalizeGtin(identifiers.barcode);
    if (barcode) queries.push({ kind: 'musicBrainzReleaseSearch', query: { barcode: barcode.digits }, basis: 'barcode' });
    const catalogNumber = tagTerm(identifiers.catalogNumber);
    if (catalogNumber) queries.push({ kind: 'musicBrainzReleaseSearch', query: { catno: catalogNumber, ...(credited.labels[0] ? { label: credited.labels[0] } : {}) }, basis: 'catalogNumber' });
    const isrc = input.fileCount === 1 ? normalizeIsrc(identifiers.isrc) : null;
    if (isrc) queries.push({ kind: 'musicBrainzIsrc', isrc, basis: 'isrc' });

    if (input.trigger === 'submitted') {
        const submitted = term(input.submitted?.text);
        if (submitted && input.submitted?.kind === 'song') songQueries(submitted);
        else if (submitted) albumQueries(submitted, 'albumText');
    } else if (input.trigger === 'tags') {
        // One file is looked up by its title, an album by the album tag; without usable tags, the folder name.
        const title = input.fileCount === 1 ? tagTerm(tags?.title) : null;
        const album = tagTerm(tags?.album);
        if (title) songQueries(title);
        else if (album) albumQueries(album, 'albumText');
        else folderQueries();
    } else folderQueries();

    const seen = new Set<string>();
    const unique = queries.filter(buildable).filter(query => {
        const key = canonical(query.kind === 'musicBrainzReleaseSearch' || query.kind === 'musicBrainzRecordingSearch' ? { kind: query.kind, query: query.query } : query);
        if (seen.has(key)) return false;
        seen.add(key); return true;
    }).slice(0, METADATA_LOOKUP_LIMITS.plannedQueries);
    return { queries: unique, rejected: unique.length ? null : 'empty' };
};
